from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    # Dictionary to store the frequency of each number
    frequency = {}

    # Count the frequency of each number
    for num in numbers:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Build the result list with numbers that appear exactly once
    result = []
    for num in numbers:
        if frequency[num] == 1:
            result.append(num)

    return result

# Test the function
