import math

def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(num)) + 1, 2):
        if num % i == 0:
            return False
    return True

def prime_fib(n):
    """Find the n-th prime Fibonacci number."""
    count = 0
    a, b = 0, 1
    while count < n:
        if is_prime(b):
            count += 1
        a, b = b, a + b
    return b

