def monotonic(l: list):
    # Check if the list is empty or has one element
    if len(l) <= 1:
        return True

    # Determine the direction of the sequence (increasing or decreasing)
    increasing = l[1] > l[0]

    for i in range(1, len(l)):
        if increasing and l[i] < l[i-1]:
            return False
        elif not increasing and l[i] > l[i-1]:
            return False

    return True

