def decimal_to_binary(decimal):
    if decimal == 0:
        return "db0db"

    binary_str = ""
    while decimal > 0:
        remainder = decimal % 2
        binary_str = str(remainder) + binary_str
        decimal //= 2

    binary_str = "db" + binary_str + "db"
    return binary_str

