def make_a_pile(n):
    # Initialize an empty list to store the number of stones in each level
    pile = []

    # Loop through each level from 1 to n
    for i in range(1, n + 1):
        # Determine the number of stones in the current level based on whether n is odd or even
        if n % 2 == 0:
            pile.append(n + 1)  # Next even number
        else:
            pile.append(n + 2)  # Next odd number

    return pile

