def minSubArraySum(nums):
    if not nums:
        return 0

    current_sum = max_sum = nums[0]

    for num in nums[1:]:
        current_sum = max(num, current_sum + num)
        max_sum = max(max_sum, current_sum)

    return max_sum

def match_parens(lst):
    # Helper function to check if a string is balanced
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Try concatenating the strings in both orders
    for i in range(len(lst)):
        first_half = lst[i]
        second_half = lst[len(lst) - 1 - i]
        if is_balanced(first_half + second_half):
            return 'Yes'
        if is_balanced(second_half + first_half):
            return 'Yes'
    return 'No'

