def valid_date(date):
    # Step 1: Check if the date string is empty
    if not date:
        return False

    # Step 2: Split the date string into day, month, and year components
    parts = date.split('-')

    # Step 3: Validate each component based on the given rules
    if len(parts) != 3:
        return False

    day, month, year = map(int, parts)

    # Validate month
    if month < 1 or month > 12:
        return False

    # Validate day
    if month == 2:
        if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
            max_days = 29
        else:
            max_days = 28
    elif month in [4, 6, 9, 11]:
        max_days = 30
    else:
        max_days = 31

    if day < 1 or day > max_days:
        return False

    # If all validations pass, return True
    return True

