def split_words(txt):
    # Check for spaces and split on them
    if ' ' in txt:
        return txt.split()

    # Check for commas and split on them
    elif ',' in txt:
        return txt.split(',')

    # Count odd-order lowercase letters
    else:
        count = 0
        for char in txt:
            if char.islower() and (ord(char) - ord('a')) % 2 != 0:
                count += 1
        return count

