def intersection(interval1, interval2):
    """Determine the intersection of two intervals and check if the length is prime."""
    start_max = max(interval1[0], interval2[0])
    end_min = min(interval1[1], interval2[1])

    # If there is no intersection, return "NO"
    if start_max > end_min:
        return "NO"

    # Calculate the length of the intersection
    length = end_min - start_max

    # Check if the length is a prime number
    if is_prime(length):
        return "YES"
    else:
        return "NO"

