def tri(n):
    # Base cases
    if n == 0:
        return []
    elif n == 1:
        return [3]

    # Initialize the first three numbers of the sequence
    sequence = [3, 3, 2]

    # Generate the sequence up to n
    for i in range(3, n + 1):
        if i % 2 == 0:
            next_value = 1 + i // 2
        else:
            next_value = sequence[i - 1] + sequence[i - 2] + sequence[i + 1]
        sequence.append(next_value)

    return sequence

