def compare_one(a, b):
    # Convert strings to floats if necessary
    if isinstance(a, str):
        a = float(a.replace(',', '.'))
    if isinstance(b, str):
        b = float(b.replace(',', '.'))

    # Compare the values
    if a > b:
        return a
    elif b > a:
        return b
    else:
        return None

