def how_many_times(string: str, substring: str) -> int:
    if len(substring) == 0:
        return 0

    count = 0
    for i in range(len(string)):
        if string[i] == substring[0]:
            # Check if the remaining part matches the substring
            if string[i:i+len(substring)] == substring:
                count += 1

    return count

