def search(lst):
    # Count the frequency of each integer
    freq_dict = {}
    for num in lst:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Find the smallest integer with a frequency >= its value
    result = -1
    for num, freq in freq_dict.items():
        if num <= freq:
            result = min(result, num)

    return result

