def is_multiply_prime(a):
    # Check for divisibility by small primes
    if a < 2 or a % 2 == 0:
        return False
    if a < 3 or a % 3 == 0:
        return False
    if a < 5 or a % 5 == 0:
        return False
    if a < 7 or a % 7 == 0:
        return False

    # Divide out common factors
    i = 7
    while i * i <= a:
        if a % i == 0:
            a //= i
        else:
            i += 2

    # Check if the remaining factor is 4
    if a == 4:
        return True
    elif a > 1:
        return False
    else:
        return True

