def get_hours(minutes: int) -> int:
    return minutes // 60

def get_minutes(minutes: int) -> int:
    return minutes % 60

def format_duration(minutes: int) -> str:
    if minutes == 0:
        return '0 minute'

    hours = get_hours(minutes)
    remaining_minutes = minutes % 60

    # Format the hours part
    if hours > 0:
        hours_str = f"{hours} hour"
        if remaining_minutes > 0:
            hours_str += "s"

    # Format the minutes part
    if remaining_minutes > 0:
        minutes_str = f"{remaining_minutes} minute"
        if hours > 0:
            minutes_str += "s"

    # Combine the parts
    if hours > 0 and remaining_minutes > 0:
        return f"{hours_str}, {minutes_str}"
    elif hours > 0:
        return hours_str
    else:
        return minutes_str

