def check_type(value: Any) -> str:
    """
    This helper function checks the type of the given value and returns a string representation of the type.
    """
    if isinstance(value, int):
        return 'int'
    elif isinstance(value, float):
        return 'float'
    elif isinstance(value, str):
        return 'str'
    else:
        return 'other'

def check_empty(value: Any) -> bool:
    """
    This helper function checks if a given iterable (like list or string) is empty and returns a boolean.
    """
    if isinstance(value, str) or isinstance(value, list):
        return len(value) == 0
    else:
        return False

def categorize_values(values: List[Any]) -> Dict[str, List[Any]]:
    """
    Categorize a list of any python values based on their type and special attributes.

    - 'int', 'float', 'str', 'other' based on their type
    - 'empty' if an iterable (like list or string) is empty

    The result is a dictionary where the keys are categories ('int', 'float', 'str', 'other', 'empty') and the values are lists containing the corresponding values from the input list.

    >>> categorize_values(['a', 3.14, 5])
    {'str': ['a'], 'float': [3.14], 'int': [5], 'other': [], 'empty': []}

    >>> categorize_values([1, 2, 'abc', {}, []])
    {'str': ['abc'], 'float': [], 'int': [1, 2], 'other': [{}], 'empty': [[]]}
    """
    categorized = {
        'int': [],
        'float': [],
        'str': [],
        'other': [],
        'empty': []
    }

    for value in values:
        category = check_type(value)
        categorized[category].append(value)

    return categorized

def is_valid_string(input_string: str) -> bool:
    """
    Check if a string is valid. A string is valid if it only contains alphanumeric characters (letters and numbers).
    Returns True if the string is valid, False otherwise.
    """
    return input_string.isalnum()

def transform_strings(strings: List[str]) -> List[str]:
    """
    Given a list of strings, transform each string into a new one according to the following rules:
    - If the string is valid (only contains alphanumeric characters), reverse the string.
    - If the string is not valid, replace each non-alphanumeric character with a hyphen '-'.
    Return the list of transformed strings, keeping the original order.
    """
    transformed = []
    for s in strings:
        if is_valid_string(s):
            transformed.append(s[::-1])
        else:
            transformed.append('-'.join([c if c.isalnum() else '-' for c in s]))
    return transformed

def count_uppercase_lowercase(string):
    """
    A function to count the number of uppercase and lowercase characters in the given string.

    If non-alphanumeric characters exist in the input, sets the count of uppercase and lowercase to -1 in the output.

    :param string: A string value
    :return: A dictionary with two keys 'uppercase' and 'lowercase', containing the count of uppercase and lowercase characters respectively.

    >>> count_uppercase_lowercase('HelloWorld')
    {'uppercase': 2, 'lowercase': 8}
    >>> count_uppercase_lowercase('GoodBye')
    {'uppercase': 2, 'lowercase': 5}
    >>> count_uppercase_lowercase('MorningSun')
    {'uppercase': 2, 'lowercase': 8}
    >>> count_uppercase_lowercase('NightMoon')
    {'uppercase': 2, 'lowercase': 7}
    >>> count_uppercase_lowercase('BadWeather')
    {'uppercase': 2, 'lowercase': 8}
    """
    if not is_valid_input(string):
        return {'uppercase': -1, 'lowercase': -1}

    uppercase_count = sum(1 for char in string if char.isupper())
    lowercase_count = sum(1 for char in string if char.islower())

    return {'uppercase': uppercase_count, 'lowercase': lowercase_count}

