def find_maximum(input_dict):
    # Check if the input dictionary is empty
    if not input_dict:
        return {}

    # Initialize variables to store the maximum value and its corresponding key
    max_value = float('-inf')
    max_key = None

    # Iterate through each key-value pair in the dictionary
    for key, value in input_dict.items():
        # Check if the current value is greater than the maximum value found so far
        if value > max_value:
            max_value = value
            max_key = key

    # Return the result as a tuple (key, value)
    return (max_key, max_value)

