import re

def convert_strings(input_list):
    # Define a dictionary to map numbers to their English words
    number_to_word = {
        '0': 'ZERO', '1': 'ONE', '2': 'TWO', '3': 'THREE', '4': 'FOUR',
        '5': 'FIVE', '6': 'SIX', '7': 'SEVEN', '8': 'EIGHT', '9': 'NINE'
    }

    def process_string(s):
        # Remove special characters
        s = re.sub(r'[!@#$%^&*()-+?_=,<>/]', '', s)

        # Replace numbers with their English words
        for num, word in number_to_word.items():
            s = s.replace(num, word)

        # Convert to uppercase
        return s.upper()

    # Apply the processing to each string in the list
    return [process_string(s) for s in input_list]

def check_vowel(s):
    """
    Given a character s, returns True if it's a vowel, False otherwise.

    For example:
    check_vowel('a') returns True
    check_vowel('b') returns False
    """
    vowel_list = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']
    return s in vowel_list

def frequency_count(s):
    """
    Given a string s, count the frequency of each vowel (case-insensitive) in the string. Return the results as a dictionary.

    For example:
    frequency_count('hello world') returns {'e': 1, 'o': 2}
    frequency_count('Python is cool') returns {'o': 3, 'i': 1}
    """
    vowel_dict = {}
    for char in s:
        if check_vowel(char):
            if char in vowel_dict:
                vowel_dict[char] += 1
            else:
                vowel_dict[char] = 1
    return vowel_dict

