from typing import List, Tuple

def minesweeper_clicked(grid: List[List[int]], position: Tuple[int, int]) -> List[List[int]]:
    x, y = position
    rows, cols = len(grid), len(grid[0])

    # Check if the position is out of bounds or already revealed
    if x < 0 or x >= rows or y < 0 or y >= cols or grid[x][y] != -1:
        return grid

    # Count the number of mines in the adjacent cells
    count_mines = 0
    for i in range(max(0, x-1), min(rows, x+2)):
        for j in range(max(0, y-1), min(cols, y+2)):
            if grid[i][j] == 1:
                count_mines += 1

    # Update the grid with the count of mines
    grid[x][y] = count_mines

    return grid

