    if len(fruits) == 1:
        return f"Oh, are those {fruits[0]} from {location}? Marvelous!"
    elif len(fruits) == 2:
        return f"Oh, are those {fruits[0]} and {fruits[1]} from {location}? Marvelous!"
    else:
        return f"Oh, are those {', '.join(fruits)} from {location}? Marvelous!"


