from typing import List

def find_rarest_element(elems: List[str]) -> str:
    # Step 1: Count the frequency of each string
    frequency = {}
    for elem in elems:
        if elem in frequency:
            frequency[elem] += 1
        else:
            frequency[elem] = 1

    # Step 2: Identify the string with the lowest frequency
    min_frequency = float('inf')
    rarest_element = None
    for elem, freq in frequency.items():
        if freq < min_frequency:
            min_frequency = freq
            rarest_element = elem

    # Step 3: Return the string if it exists; otherwise, return None
    if rarest_element is not None:
        return rarest_element
    else:
        return None

