def create_alias(name: str) -> str:
    # Define vowels and consonants
    vowels = "aeiouAEIOU"
    consonants = "bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ"

    # Cycle functions for vowels and consonants
    def cycle_vowel(vowel):
        index = vowels.index(vowel)
        return vowels[(index + 1) % len(vowels)]

    def cycle_consonant(consonant):
        index = consonants.index(consonant)
        return consonants[(index + 1) % len(consonants)]

    # Process each character in the input name
    alias = ""
    for char in name:
        if char.isalpha():
            if char in vowels:
                alias += cycle_vowel(char)
            else:
                alias += cycle_consonant(char)
        else:
            alias += char

    return alias

