def evaluate_poker_hand(hand: list):
    # Extract card values and convert them to integers
    values = [int(card[0]) for card in hand]

    # Count the frequency of each card value
    value_counts = {}
    for value in values:
        if value in value_counts:
            value_counts[value] += 1
        else:
            value_counts[value] = 1

    # Check for different hand types
    if len(value_counts) == 5 and sorted(values) == list(range(min(values), max(values) + 1)):
        return 4 * max(values)  # Five of a kind

    if len(value_counts) == 4:
        return 3 * max(value_counts.keys())  # Four of a kind

    if len(value_counts) == 3 and 2 in value_counts.values():
        return 2 * max(value_counts.keys())  # Full house

    if len(set(values)) == 5:
        return sum(values)  # Flush

    if len(set(values)) == 4:
        return 3 * max(values)  # Straight

    if len(set(values)) == 3:
        return 2 * max(values)  # Three of a kind

    if len(set(values)) == 2:
        return max(values)  # Pair

    return 0  # No valid hand

