def vampires_in_matrix(m: list):
    def is_vampire(x, y):
        return m[x][y] == 2

    def is_human(x, y):
        return m[x][y] == 1

    rows = len(m)
    cols = len(m[0])
    dangerous_humans = 0

    for i in range(rows):
        for j in range(cols):
            if is_human(i, j):
                # Check up
                if i > 0 and is_vampire(i - 1, j):
                    dangerous_humans += 1
                # Check down
                if i < rows - 1 and is_vampire(i + 1, j):
                    dangerous_humans += 1
                # Check left
                if j > 0 and is_vampire(i, j - 1):
                    dangerous_humans += 1
                # Check right
                if j < cols - 1 and is_vampire(i, j + 1):
                    dangerous_humans += 1

    return dangerous_humans

