def generate_pattern(n: int) -> List[str]:
    if n <= 0:
        return []

    # Ascending part
    ascending = [str(i) for i in range(1, n + 1)]

    # Descending part
    descending = [str(i) for i in range(n - 1, 0, -1)]

    # Combine both parts and join them with commas
    result = ', '.join(ascending + descending)

    return result.split(', ')

def crossword_validator(grid: list, words: list):
    def is_word_in_row(word, row):
        return word == ''.join(row)

    def is_word_in_column(word, col):
        return word == ''.join(col)

    def is_word_in_diagonal_up(word, start_row, start_col):
        n = len(grid)
        for i in range(n):
            if i + start_row >= n or i + start_col >= n:
                break
            if word == ''.join(grid[i + start_row][i + start_col]):
                return True
        return False

    def is_word_in_diagonal_down(word, start_row, start_col):
        n = len(grid)
        for i in range(n):
            if i + start_row < 0 or i + start_col < 0:
                break
            if word == ''.join(grid[i + start_row][i + start_col]):
                return True
        return False

    # Check horizontal and vertical directions
    for word in words:
        if not any(is_word_in_row(word, row) for row in grid) and \
           not any(is_word_in_column(word, col) for col in zip(*grid)):
            return False

    # Check diagonal directions
    for word in words:
        if not is_word_in_diagonal_up(word, 0, 0) and \
           not is_word_in_diagonal_down(word, 0, 0):
            return False

    return True

