def pathfinder(maze, start, end):
    if start == end or maze[start[0]][start[1]] == 1:
        return []

    directions = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}
    queue = [(start, [])]
    visited = set([start])

    while queue:
        current, path = queue.pop(0)
        if current == end:
            return path

        for direction in directions.values():
            next_row, next_col = current[0] + direction[0], current[1] + direction[1]
            if 0 <= next_row < len(maze) and 0 <= next_col < len(maze[0]) and maze[next_row][next_col] == 0 and (next_row, next_col) not in visited:
                visited.add((next_row, next_col))
                queue.append(((next_row, next_col), path + [direction]))

    return []

from typing import List

class Solution:
    def spiderWebJump(self, arr: List[List[int]]) -> int:
        # Initialize the dimensions of the array
        m, n = len(arr), len(arr[0])

        # Create a DP table filled with infinity
        dp = [[float('inf')] * n for _ in range(m)]

        # Set the starting cell's energy to 0
        dp[0][0] = 0

        # Iterate through each cell in the array
        for i in range(m):
            for j in range(n):
                if arr[i][j] == 0:
                    continue

                # Check the four possible directions (up, down, left, right)
                for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    x, y = i + dx, j + dy
                    if 0 <= x < m and 0 <= y < n and arr[x][y] != 0:
                        # Update the DP value based on the minimum energy required
                        dp[i][j] = min(dp[i][j], dp[x][y] + arr[i][j])

        # The minimum energy required to reach the safe cell is in the bottom-right corner of the DP table
        return dp[m-1][n-1]

