def alien_encoding(string, list_of_alphabets):
    if not string or not list_of_alphabets:
        return string

    # Loop through the string and replace characters with corresponding alphabets from the list
    encoded_string = ''.join(list_of_alphabets[i % len(list_of_alphabets)] for i in range(len(string)))

    return encoded_string

def magical_transformation(s):
    vowels = 'aeiouAEIOU'
    consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ'
    result = []

    for char in s:
        if char in vowels:
            # Replace vowel with the next vowel
            result.append(vowels[(vowels.index(char) + 1) % len(vowels)])
        elif char in consonants:
            # Replace consonant with the next consonant
            result.append(consonants[(consonants.index(char) + 1) % len(consonants)])
        else:
            # Keep other characters unchanged
            result.append(char)

    # Transform odd indices from '?' to '!' or '! to '?'
    for i in range(0, len(result), 2):
        if result[i] == '?':
            result[i] = '!'
        elif result[i] == '!':
            result[i] = '?'

    return ''.join(result)

