def transform_string(s):
    vowels = "aeiouAEIOU"
    next_vowels = "eiouEIOU"
    prev_consonants = "bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ"

    result = []
    for index, char in enumerate(s):
        if index % 2 != 0 and char.isalpha():
            # Swap case of odd-indexed alphabetic characters
            result.append(char.swapcase())
        elif char.lower() in vowels:
            # Replace vowels with the next vowel in the sequence
            result.append(next_vowels[vowels.index(char.lower())])
        elif char.lower() in prev_consonants:
            # Replace consonants with the preceding consonant in the sequence
            result.append(prev_consonants[prev_consonants.index(char.lower())])
        else:
            # Keep non-alphabetic characters unchanged
            result.append(char)

    return ''.join(result)

