def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def magical_sequence(start, end, divisor):
    """Return a list of all numbers in the range [start, end] inclusive, that are divisible by 'divisor' and are prime numbers."""
    result = []
    for num in range(start, end + 1):
        if num % divisor == 0 and is_prime(num):
            result.append(num)
    return result

