def food_order(menu, order):
    # Create a copy of the original menu to avoid modifying it directly
    final_menu = menu.copy()

    # Iterate through each item in the order
    for item, changes in order.items():
        if 'remove' in changes:
            # Remove the specified ingredients from the current item's list
            final_menu[item] = [ingredient for ingredient in final_menu[item] if ingredient not in changes['remove']]

        if 'add' in changes:
            # Add the specified ingredients to the current item's list
            final_menu[item].extend(changes['add'])

    return final_menu

