from itertools import combinations

def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_anagram_pairs(n):
    # Step 1: Generate all prime numbers up to n
    primes = [num for num in range(2, n+1) if is_prime(num)]

    # Step 2: Check for anagrams
    anagram_pairs = []
    for p1, p2 in combinations(primes, 2):
        if sorted(str(p1)) == sorted(str(p2)):
            anagram_pairs.append((p1, p2))

    # Step 3: Sort the result
    anagram_pairs.sort(key=lambda x: (x[0], x[1]))

    return anagram_pairs

