def meal_calculator(customers, meals):
    # Initialize an empty dictionary to store the total calories consumed by each customer
    total_calories = {}

    # Iterate over each customer in the list
    for customer in customers:
        # Check if the customer exists in the meals dictionary
        if customer in meals:
            # Sum up the calories from all meals consumed by the customer
            total_calories[customer] = sum(meal['calories'] for meal in meals[customer])
        else:
            # If the customer does not have any meals, set their total calories to 0
            total_calories[customer] = 0

    # Return the dictionary containing the total calories consumed by each customer
    return total_calories

def magical_sorting(arr):
    # Check if the array is already sorted
    if arr == sorted(arr):
        return True

    # Find the pivot point
    pivot = None
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            pivot = i
            break

    if pivot is None:
        return False

    # Count the number of rotations needed
    rotations_needed = len(arr) - pivot - 1

    # Check if there exists a valid swap
    for i in range(pivot + 1, len(arr)):
        if arr[i] < arr[i - 1]:
            return False

    return True

