def planet_path(planets, path):
    # Check for empty path
    if not path:
        return False

    # Check for invalid planets
    for planet in path:
        if planet not in planets:
            return False

    # Validate the path
    for i in range(len(path) - 1):
        if path[i] not in planets[path[i + 1]]:
            return False

    return True

