def magical_string_transformer(input_str):
    vowels = 'aeiou'
    consonants = ''.join([chr(i) for i in range(97, 123) if chr(i) not in vowels])

    def next_vowel(c):
        return vowels[(vowels.index(c.lower()) + 1) % len(vowels)]

    def next_consonant(c):
        return consonants[(consonants.index(c.lower()) + 1) % len(consonants)]

    result = []
    for char in input_str:
        if char.isalpha():
            if char.islower():
                result.append(next_vowel(char))
            else:
                result.append(next_vowel(char.upper()))
        elif char.isdigit():
            result.append(str((int(char) + 1) % 10))
        elif char == '?':
            if len(result) % 2 == 0:
                result.append('!')
            else:
                result.append('?')
        else:
            result.append(char)

    return ''.join(result)

