def word_spiral(arr):
    if not arr:
        return ""

    result = []
    top, bottom, left, right = 0, len(arr) - 1, 0, len(arr[0]) - 1

    while top <= bottom and left <= right:
        # Add elements from the top row
        for i in range(left, right + 1):
            result.append(arr[top][i])
        top += 1

        # Add elements from the right column
        for i in range(top, bottom + 1):
            result.append(arr[i][right])
        right -= 1

        # Add elements from the bottom row (if not already added)
        if top <= bottom:
            for i in range(right, left - 1, -1):
                result.append(arr[bottom][i])
            bottom -= 1

        # Add elements from the left column (if not already added)
        if left <= right:
            for i in range(bottom, top - 1, -1):
                result.append(arr[i][left])
            left += 1

    return ''.join(result)

