def planet_population(dict_of_planets):
    """
    Given a dictionary where each key represents a planet
    and its value is a list of population features.
    Each list contains two elements: ["Population", "Size"].
    The "Population" is a positive integer representing the number of inhabitants,
    and "Size" is a positive integer representing the planet's size in square kilometers.

    This function returns a new dictionary with planets as keys and their population densities as values.
    Population density is calculated as population / size, rounded to two decimal places.
    If a planet's size or population is missing, it is ignored.

    Examples:
    planet_population({"Earth": [7000000000, 15000000], "Mars": [0, 25000000]}) == {'Earth': 466.67, 'Mars': 0.0}
    planet_population({}) == {}
    planet_population({"Jupiter": [None, 64000000]}) == {}
    planet_population({"Venus": [500000000, None]}) == {}
    """
    result = {}
    for planet, features in dict_of_planets.items():
        if all(feature is not None for feature in features):
            population = features[0]
            size = features[1]
            density = round(population / size, 2)
            result[planet] = density
    return result

