def spaceship_trajectory(spaceship_data):
    status = 'On Ground'
    for action, distance in spaceship_data:
        if action == 'Launch':
            if status != 'On Ground':
                return 'Invalid Action Sequence'
            status = 'In Space'
        elif action == 'Move':
            if status != 'In Space':
                return 'Invalid Action Sequence'
        elif action == 'Land':
            if status != 'In Space':
                return 'Invalid Action Sequence'
            status = 'On Ground'
        else:
            return 'Invalid Action Sequence'
    return status

