def get_magic_indices(lst):
    def digit_product(n):
        return int(''.join(str(digit) for digit in str(abs(n))))

    magic_indices = []
    for i in range(len(lst)):
        if lst[i] % i == 0 and digit_product(lst[i]) == i:
            magic_indices.append(i)
    return sorted(magic_indices)

