from typing import List, Optional, Tuple

def longest_substring(strings: List[str]) -> Tuple[Optional[str], Optional[int]]:
    if not strings:
        return (None, None)

    max_length = 0
    longest_string = None
    longest_index = None

    for i, s in enumerate(strings):
        current_length = 0
        for j in range(len(s)):
            if s[j].lower() in ['a', 'e', 'i', 'o', 'u']:
                current_length += 1
                if current_length > max_length:
                    max_length = current_length
                    longest_string = s
                    longest_index = i
            else:
                break

    return (longest_string, longest_index)

from typing import List

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def multiple_greatest_common_divisors(numbers: List[int]) -> int:
    if len(numbers) < 2 or len(numbers) > 10:
        raise ValueError("List must contain between 2 and 10 elements.")

    if len(set(numbers)) != len(numbers):
        raise ValueError("All elements in the list must be unique.")

    if any(num <= 0 for num in numbers):
        raise ValueError("All elements in the list must be positive integers.")

    # Calculate the GCD of the first two numbers
    current_gcd = gcd(numbers[0], numbers[1])

    # Iterate through the rest of the numbers to find the GCD
    for i in range(2, len(numbers)):
        current_gcd = gcd(current_gcd, numbers[i])

    if current_gcd == 1:
        return -1
    else:
        return current_gcd

