from collections import Counter

def count_distinct_characters_substrings(string: str, length: int) -> dict:
    if length > len(string):
        return {}

    distinct_chars = Counter(string[:length])
    result = {string[i:i+length]: len(distinct_chars) for i in range(len(string) - length + 1)}

    return result

def how_many_times(string: str, substrings: list) -> dict:
    # Check for empty substrings
    if any(substring == "" for substring in substrings):
        return "Substrings cannot be empty"

    # Initialize the result dictionary
    result = {}

    # Iterate through the string using a sliding window
    for i in range(len(string)):
        for j in range(i + len(max(substrings)), len(string) + 1):
            substring = string[i:j]
            if substring in substrings:
                result[substring] = result.get(substring, 0) + 1

    return result

