def largest_prime_divisor(n: int, k: int) -> int:
    # Step 1: Find all prime factors of n
    prime_factors = []
    for i in range(2, int(math.sqrt(n)) + 1):
        while n % i == 0:
            prime_factors.append(i)
            n //= i

    # Step 2: Sort the prime factors in descending order
    prime_factors.sort(reverse=True)

    # Step 3: Select the kth largest prime
    if k > len(prime_factors):
        return -1
    else:
        return prime_factors[k-1]

