def sieve_of_eratosthenes(limit):
    primes = [True] * (limit + 1)
    primes[0], primes[1] = False, False
    for i in range(2, int(limit**0.5) + 1):
        if primes[i]:
            for j in range(i*i, limit + 1, i):
                primes[j] = False
    return [i for i in range(2, limit + 1) if primes[i]]

def factorize_and_count(n: int) -> List[Tuple[int, int]]:
    if n == 1:
        return []

    # Find all prime factors using the Sieve of Eratosthenes
    primes = sieve_of_eratosthenes(int(n**0.5))
    factor_counts = {}

    for p in primes:
        while n % p == 0:
            if p in factor_counts:
                factor_counts[p] += 1
            else:
                factor_counts[p] = 1
            n //= p

    # If n is still greater than 1, it must be a prime number
    if n > 1:
        factor_counts[n] = 1

    return list(factor_counts.items())

