def incr_list_conditionally(l: list, ignore: list):
    # Check if all elements in the ignore list are integers
    for item in ignore:
        if not isinstance(item, int):
            return "Ignore list should only contain integers"

    # Create a new list to store the result
    result = []

    # Iterate through the input list l
    for item in l:
        # Check if the item is in the ignore list
        if item in ignore:
            result.append(item)
        else:
            result.append(item + 1)

    return result

