def fib4_memo(n: int, m: int):
    # Check if the input is valid
    if n < 0 or m > n:
        return "Invalid input"

    # Initialize memoization dictionary
    memo = {0: 0, 1: 0, 2: 2, 3: 0}

    def helper(i):
        if i in memo:
            return memo[i]

        # Calculate the value using memoization
        memo[i] = helper(i - 1) + helper(i - 2) + helper(i - 3) + helper(i - 4)
        return memo[i]

    # Calculate the n-th element of the Fibonacci sequence
    result = helper(n)

    # Return the m-th element from the end
    return result - (n - m)

