def below_above_threshold(l: list, t1: int, t2: int, s: str) -> bool:
    if s == 'below':
        for i in range(len(l)):
            if l[i] >= t1:
                return False
        return True
    elif s == 'above':
        for i in range(len(l)):
            if l[i] <= t2:
                return False
        return True
    else:
        return -1

