def fib(n: int, x: int, operation: str) -> int:
    # Initialize the first two Fibonacci numbers
    a, b = 0, 1

    # Generate the Fibonacci sequence up to the nth term
    for i in range(2, n + 1):
        if i % x == 0:
            if operation == "square":
                b *= b
            elif operation == "add_two":
                b += 2
            else:
                b = 0
        a, b = b, a + b

    return b

