def monotonic_sublist(l: list, k: int) -> bool:
    # Check for increasing sublists
    for i in range(len(l) - k + 1):
        if all(l[i] <= l[i + j] for j in range(1, k)):
            return True

    # Check for decreasing sublists
    for i in range(len(l) - k + 1):
        if all(l[i] >= l[i + j] for j in range(1, k)):
            return True

    return False

