def largest_prime_factor(n: int, m: int):
    """ Find the largest prime factor of n if m is prime, otherwise find the smallest prime factor of n """
    if is_prime(m):
        # If m is prime, find the largest prime factor of n
        for i in range(n, 1, -1):
            if n % i == 0 and is_prime(i):
                return i
    else:
        # If m is not prime, find the smallest prime factor of n
        for i in range(2, n + 1):
            if n % i == 0 and is_prime(i):
                return i

