def advancedDigitSum(s, t):
    # Function to calculate the sum of ASCII codes of uppercase letters in a string
    def sum_uppercase_ascii(s):
        return sum(ord(c) for c in s if c.isupper())

    # Function to calculate the sum of ASCII codes of lowercase letters in a string
    def sum_lowercase_ascii(s):
        return sum(ord(c) for c in s if c.islower())

    # Calculate sums for both strings
    sum_s = sum_uppercase_ascii(s)
    sum_t = sum_lowercase_ascii(t)

    # Return the results as a tuple
    return (sum_s, sum_t)

