def advanced_search(lst, f):
    # Step 1: Count frequencies
    freq_dict = {}
    for num in lst:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Step 2: Check conditions and find the greatest valid integer
    max_valid_integer = -1
    for num, freq in freq_dict.items():
        if num >= num and freq % f == 0:
            max_valid_integer = max(max_valid_integer, num)

    return max_valid_integer

