import math

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def get_primes_up_to(limit):
    """Get all prime numbers up to a given limit."""
    primes = []
    for num in range(2, limit + 1):
        if is_prime(num):
            primes.append(num)
    return primes

def is_multiply_prime(a, b):
    """Check if a is the multiplication of exactly b prime numbers."""
    if a < 2 or b < 1:
        return False

    # Get all prime numbers up to the square root of a
    primes_up_to_sqrt_a = get_primes_up_to(int(math.sqrt(a)))

    # Check if a can be expressed as the product of exactly b prime numbers
    if len(primes_up_to_sqrt_a) < b:
        return False

    # Try to find the prime factors
    prime_factors = []
    for prime in primes_up_to_sqrt_a:
        while a % prime == 0:
            prime_factors.append(prime)
            a //= prime

    # Check if we have found exactly b prime factors
    if len(prime_factors) != b:
        return False

    # Sort the prime factors
    prime_factors.sort()

    return True, prime_factors

