import math

def complex_power(x, n, m):
    # Check if n is 1
    if n == 1:
        return x == 1

    # Check if m is 1
    if m == 1:
        return x == 1

    # Check if n and m are both greater than 1
    if n <= 1 or m <= 1:
        return False

    # Prime factorization of x
    factors_x = {}
    temp_x = x
    while temp_x > 1:
        for i in range(2, int(math.sqrt(temp_x)) + 1):
            while temp_x % i == 0:
                if i in factors_x:
                    factors_x[i] += 1
                else:
                    factors_x[i] = 1
                temp_x //= i
        if temp_x > 1:
            factors_x[temp_x] = 1
            temp_x = 1

    # Prime factorization of n and m
    factors_n = {}
    temp_n = n
    while temp_n > 1:
        for i in range(2, int(math.sqrt(temp_n)) + 1):
            while temp_n % i == 0:
                if i in factors_n:
                    factors_n[i] += 1
                else:
                    factors_n[i] = 1
                temp_n //= i
        if temp_n > 1:
            factors_n[temp_n] = 1
            temp_n = 1

    factors_m = {}
    temp_m = m
    while temp_m > 1:
        for i in range(2, int(math.sqrt(temp_m)) + 1):
            while temp_m % i == 0:
                if i in factors_m:
                    factors_m[i] += 1
                else:
                    factors_m[i] = 1
                temp_m //= i
        if temp_m > 1:
            factors_m[temp_m] = 1
            temp_m = 1

    # Check if x can be expressed as n^a * m^b
    if len(factors_x) != len(factors_n) or len(factors_x) != len(factors_m):
        return False

    for key in factors_x:
        if factors_x[key] != factors_n[key]:
            return False

    for key in factors_x:
        if factors_x[key] != factors_m[key]:
            return False

    return True

# Test cases
