from math import sqrt

def prime_length(string, opt=None):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    if opt == 'letters':
        unique_letters = set(string.lower())
        return is_prime(len(unique_letters))
    elif opt == 'words':
        # Splitting the string into words based on spaces and commas, ignoring empty words
        words = [word.strip() for word in string.replace(',', ' ').split()]
        return is_prime(len(words))
    else:
        # Default case: checking if the overall length of the string is a prime number
        return is_prime(len(string))

# Test cases
print(prime_length('Hello', 'letters'))  # Expected output: False
