def sort_array(array, pivot):
    # Step 1: Rearrange the array
    left = 0
    right = len(array) - 1
    while left < right:
        while left < right and array[left] <= pivot:
            left += 1
        while left < right and array[right] >= pivot:
            right -= 1
        if left < right:
            array[left], array[right] = array[right], array[left]

    # Step 2: Sort the parts of the array
    pivot_value = array[pivot]
    if (pivot_value + array[0]) % 2 == 0:
        # Sort the first part in descending order
        for i in range(pivot):
            for j in range(i + 1, pivot):
                if array[j] > array[i]:
                    array[i], array[j] = array[j], array[i]
    else:
        # Sort the first part in ascending order
        for i in range(pivot):
            for j in range(i + 1, pivot):
                if array[j] < array[i]:
                    array[i], array[j] = array[j], array[i]

    # Sort the second part in the opposite order of the first part
    if (pivot_value + array[pivot]) % 2 == 0:
        # Sort the second part in ascending order
        for i in range(pivot, len(array)):
            for j in range(i + 1, len(array)):
                if array[j] < array[i]:
                    array[i], array[j] = array[j], array[i]
    else:
        # Sort the second part in descending order
        for i in range(pivot, len(array)):
            for j in range(i + 1, len(array)):
                if array[j] > array[i]:
                    array[i], array[j] = array[j], array[i]

    return array

