def encode_complex(message, shift, key):
    # Define vowels and their corresponding shifted positions in the alphabet
    vowels = "aeiouAEIOU"
    shifted_vowels = [chr((ord(vowel) - ord('a') + shift) % 26 + ord('a')) if vowel.islower() else chr((ord(vowel) - ord('A') + shift) % 26 + ord('A')) for vowel in vowels]

    # Create a mapping from consonants to characters in the key
    consonant_to_key = {consonant: key[ord(consonant) - ord('a')] for consonant in set(key) if consonant.isalpha()}

    # Encode the message
    encoded_message = ""
    for char in message:
        if char.isalpha():
            if char.isupper():
                base = ord('A')
            else:
                base = ord('a')

            # Swap case
            if char.isupper():
                encoded_char = chr(base + (ord(char) - base + shift) % 26)
            else:
                encoded_char = chr(base + (ord(char) - base + shift) % 26)

            # Replace vowels
            if encoded_char in vowels:
                encoded_char = shifted_vowels[vowels.index(encoded_char)]

            # Replace consonants
            if encoded_char in consonant_to_key:
                encoded_char = consonant_to_key[encoded_char]

        else:
            encoded_char = char

        encoded_message += encoded_char

    return encoded_message

