import re

def multiplyComplex(a, b):
    # Define a regular expression pattern for matching complex numbers in the form "a+bi"
    pattern = r"(-?\d+) \+(\d+)i"

    # Extract real and imaginary parts from the input strings
    match_a = re.match(pattern, a)
    match_b = re.match(pattern, b)

    if not match_a or not match_b:
        raise ValueError("Invalid complex number format")

    real_a, imag_a = map(int, match_a.groups())
    real_b, imag_b = map(int, match_b.groups())

    # Perform the multiplication
    real_product = real_a * real_b - imag_a * imag_b
    imag_product = real_a * imag_b + real_b * imag_a

    # Format the result as a dictionary
    result = {'real': real_product, 'imaginary': imag_product}

    return result

