def closest_integer(value, base):
    # Step 1: Convert the input string to its decimal equivalent
    decimal_value = int(value, base)

    # Step 2: Round the decimal value to the nearest integer
    rounded_value = round(decimal_value)

    # Step 3: Convert the rounded decimal value back to the specified base
    def to_base(n, b):
        if n == 0:
            return '0'
        digits = []
        while n:
            digits.append(int(n % b))
            n //= b
        return ''.join(str(x) for x in digits[::-1])

    # Step 4: Handle cases where the number is exactly halfway between two integers
    if abs(rounded_value - decimal_value) == 0.5:
        if decimal_value > 0:
            return to_base(rounded_value + 1, base)
        else:
            return to_base(rounded_value - 1, base)

    return to_base(rounded_value, base)

