def correct_bracket_sequence_and_count(string: str, bracket: str) -> tuple:
    stack = []
    count = 0

    for char in string:
        if char == bracket:
            stack.append(char)
        elif char != bracket and stack:
            stack.pop()
        else:
            continue

    # Check if all brackets are balanced
    if not stack:
        return True, count
    else:
        return False, count

