def planet_to_roman_distance(planet1, planet2):
    # Define the order of planets from the Sun
    planets = ["mercury", "venus", "earth", "mars", "jupiter", "saturn", "uranus", "neptune"]

    # Check if both planets are valid
    if planet1 not in planets or planet2 not in planets:
        return {}

    # Find the indices of the planets
    index1, index2 = planets.index(planet1), planets.index(planet2)

    # Ensure index1 is less than index2 for iteration
    if index1 > index2:
        index1, index2 = index2, index1

    # Generate the Roman numerals for the planets between them
    roman_numerals = {planets[i]: str(i + 1) for i in range(index1 + 1, index2)}

    return roman_numerals

