from typing import List, Tuple, Optional

def account_operations(operations: List[int]) -> Tuple[Optional[int], Optional[int], bool]:
    balance = 0
    max_withdrawal = None
    min_deposit = None
    below_zero_detected = False

    for op in operations:
        balance += op

        if op < 0:
            if balance < 0:
                below_zero_detected = True
            else:
                # Update min_deposit if it's not set or this is a smaller value
                if min_deposit is None or op < min_deposit:
                    min_deposit = op
        elif op > 0:
            # Update max_withdrawal if it's not set or this is a larger value
            if max_withdrawal is None or op > max_withdrawal:
                max_withdrawal = op

    return (max_withdrawal, min_deposit, below_zero_detected)

