def sum_product_triples(n: int) -> Tuple[int, int]:
    # Generate the array a
    a = [i * i - i + 1 for i in range(1, n + 1)]

    # Initialize variables to store the sum and product of the first elements of valid triples
    total_sum = 0
    total_product = 1

    # Iterate through all possible triples (i, j, k) with i < j < k
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    total_sum += a[i]
                    total_product *= a[i]

    # Return the result as a tuple
    return (total_sum, total_product)

