import hashlib

def md5_nested_parens(paren_string: str) -> List[str]:
    if paren_string == '':
        return []

    def calculate_depth(s):
        depth = 0
        max_depth = 0
        for char in s:
            if char == '(':
                depth += 1
                max_depth = max(max_depth, depth)
            elif char == ')':
                depth -= 1
        return max_depth

    result = []
    for group in paren_string.split():
        if group.strip() == '':
            result.append('None')
        else:
            result.append(hashlib.md5(group.encode()).hexdigest())

    return result

