def minSubArraySumEvenOdd(nums):
    def count_digits(n):
        return len(str(abs(n)))

    min_sum = float('inf')
    even_count = 0
    odd_count = 0

    for i in range(len(nums)):
        current_sum = 0
        current_even_count = 0
        current_odd_count = 0

        for j in range(i, len(nums)):
            current_sum += nums[j]
            current_even_count += count_digits(current_sum % 2)
            current_odd_count += count_digits((current_sum + 1) % 2)

            if current_sum < min_sum:
                min_sum = current_sum
                even_count = current_even_count
                odd_count = current_odd_count

    return (min_sum, even_count, odd_count)

