def is_palindrome(num):
    """Check if a number is a palindrome."""
    return str(num) == str(num)[::-1]

def count_even_odd_palindromes(n):
    """Count even and odd palindromes up to n."""
    even_count = 0
    odd_count = 0
    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
    return even_count, odd_count

def even_odd_zero_sum(l, n):
    even_count, odd_count = count_even_odd_palindromes(n)
    even_sum = even_count * (even_count - 1) // 2
    odd_sum = odd_count * (odd_count - 1) // 2

    even_found = any(x + y == even_sum for x in l for y in l if x != y)
    odd_found = any(x + y == odd_sum for x in l for y in l if x != y)

    return (even_found, odd_found)

