def pluck_and_prod(arr: List[int]) -> Tuple[List[int], int]:
    if not arr:
        return ([], None)

    # Find the smallest even value and its index
    smallest_even = float('inf')
    smallest_index = -1
    for i, val in enumerate(arr):
        if val % 2 == 0 and val < smallest_even:
            smallest_even = val
            smallest_index = i

    if smallest_index == -1:
        return ([], None)

    # Remove the smallest even value from the array
    arr.pop(smallest_index)

