def product_of_odd_prime_factors(n):
    """Return the product of unique odd prime factors of n."""
    product = 1
    # Check for odd factors starting from 3
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            product *= i
            n //= i
    # If n is still greater than 2, it must be a prime number (odd)
    if n > 2:
        product *= n
