import math

def transform_dict(input_dict):
    # Check if the input dictionary is empty or contains non-string keys
    if not isinstance(input_dict, dict) or any(not isinstance(key, str) for key in input_dict.keys()):
        return {}

    # Check if all keys are either all uppercase or all lowercase
    all_upper = all(key.isupper() for key in input_dict.keys())
    all_lower = all(key.islower() for key in input_dict.keys())
    if not (all_upper or all_lower):
        return {}

    # Transform the dictionary
    transformed_dict = {}
    for key, value in input_dict.items():
        try:
            num = float(value)
            rounded_num = round(num)
            if abs(rounded_num - num) == 0.5:
                # Round away from zero
                transformed_dict[key] = int(math.copysign(rounded_num, num))
            else:
                transformed_dict[key] = rounded_num
        except ValueError:
            # Ignore non-numeric values
            continue

    return transformed_dict

def happy_case_string(s):
    # Step 1: Check if the string is happy
    if len(s) < 3:
        return s[::-1]

    # Step 2: Check if every 3 consecutive letters are distinct
    for i in range(len(s) - 2):
        if s[i] == s[i + 1] or s[i] == s[i + 2] or s[i + 1] == s[i + 2]:
            return s

    # Step 3: Reverse the case of each letter in the string
    result = ""
    for char in s:
        if char.isalpha():
            if char.islower():
                result += char.upper()
            else:
                result += char.lower()
        else:
            result += char

    return result

