def odd_fibfib(n: int):
    # Helper function to calculate the product of odd digits
    def product_of_odd_digits(num):
        return int(''.join(str(digit) for digit in str(num) if digit % 2 != 0))

    # Helper function to check if all digits are even
    def all_even_digits(num):
        return all(int(digit) % 2 == 0 for digit in str(num))

    # Initialize the first three odd Fibonacci numbers
    fib_sequence = [0, 0, 1]

    # Generate the odd Fibonacci numbers up to the nth term
    while len(fib_sequence) < n:
        next_fib = fib_sequence[-1] + fib_sequence[-2] + fib_sequence[-3]
        fib_sequence.append(next_fib)

    # Apply the rules to the nth term
    if fib_sequence[n-1] % 2 == 0:
        fib_sequence[n-1] = product_of_odd_digits(fib_sequence[n-1])
    elif all_even_digits(fib_sequence[n-1]):
        fib_sequence[n-1] = 0

    return fib_sequence[n-1]

