def prefixes_histogram(string: str) -> Dict[str, Dict[str, int]]:
    if not string:
        return {}

    result = {}
    current_prefix = ""
    for char in string:
        current_prefix += char
        if current_prefix not in result:
            result[current_prefix] = {}

        # Update the histogram for the current prefix
        for i in range(1, len(current_prefix) + 1):
            substring = current_prefix[:i]
            if substring in result[current_prefix]:
                result[current_prefix][substring] += 1
            else:
                result[current_prefix][substring] = 1

    return result

