from typing import List

def evaluate_common_expressions(operators: List[str], operand_lists: List[List[int]]) -> int:
    # Find common operands between all operand lists
    common_operands = set(operand_lists[0]).intersection(*operand_lists[1:])

    if not common_operands:
        return None

    # Sort the common operands
    common_operands_sorted = sorted(common_operands)

    # Evaluate the algebraic expression using the common operands and operators
    result = 0
    for i, op in enumerate(operators):
        if op == '+':
            result += common_operands_sorted[i]
        elif op == '-':
            result -= common_operands_sorted[i]
        elif op == '*':
            result *= common_operands_sorted[i]
        elif op == '//':
            result //= common_operands_sorted[i]
        elif op == '**':
            result **= common_operands_sorted[i]

    return result

def match_and_remove_unbalanced(text):
    # Helper function to check if parentheses are balanced
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Helper function to remove vowels from a string
    def remove_vowels(s):
        vowels = "aeiouAEIOU"
        return ''.join(char for char in s if char not in vowels)

    # Check if the parentheses are balanced
    if is_balanced(text):
        return text
    else:
        # Remove vowels from the string
        return remove_vowels(text)

