def sort_prime_even(l: list, x, y):
    """Sorts the even indices of the list l and replaces the original elements with x or y based on primality."""
    # Extract even indices
    even_indices = [i for i in range(len(l)) if i % 2 == 0]

    # Sort the elements at even indices
    sorted_even_elements = sorted(l[i] for i in even_indices)

    # Replace the original elements at even indices with x or y
    result = l[:]
    for i, value in enumerate(sorted_even_elements):
